/**
 * Seedling Kenya — Cloudflare Worker
 * Serves the static site (index.html, styles.css, script.js) plus binary
 * assets (intro video, product photos) with sensible cache headers.
 *
 * Two deployment options:
 *   1. Static assets (recommended): upload the folder with
 *      `npx wrangler deploy` and an `assets` binding, or via the
 *      dashboard "Workers & Pages → Create → Upload assets".
 *   2. Single-file worker: bundle everything into ASSETS_JSON below with
 *      `node build-worker.mjs` and paste worker.js into the dashboard.
 *      Binary assets are base64-encoded ("b64:" prefix) and decoded here.
 */

const ASSETS = {
  "/": { file: "index.html", type: "text/html; charset=utf-8", cache: "public, max-age=0, must-revalidate" },
  "/index.html": { file: "index.html", type: "text/html; charset=utf-8", cache: "public, max-age=0, must-revalidate" },
  "/styles.css": { file: "styles.css", type: "text/css; charset=utf-8", cache: "public, max-age=86400" },
  "/script.js": { file: "script.js", type: "application/javascript; charset=utf-8", cache: "public, max-age=86400" },
  "/avocado-timelapse.mp4": { file: "avocado-timelapse.mp4", type: "video/mp4", cache: "public, max-age=604800" },
  "/poster.jpg": { file: "poster.jpg", type: "image/jpeg", cache: "public, max-age=604800" },
  "/apple.webp": { file: "apple.webp", type: "image/webp", cache: "public, max-age=604800" },
  "/avocado.webp": { file: "avocado.webp", type: "image/webp", cache: "public, max-age=604800" },
  "/passion.webp": { file: "passion.webp", type: "image/webp", cache: "public, max-age=604800" },
};

function decodeAsset(value) {
  // "b64:..." values come from the single-file bundle (build-worker.mjs)
  if (typeof value === "string" && value.startsWith("b64:")) {
    const bin = atob(value.slice(4));
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }
  return value;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    let path = url.pathname;

    if (path !== "/" && path.endsWith("/")) path = path.slice(0, -1);

    const asset = ASSETS[path] || ASSETS["/"];
    const headers = {
      "Content-Type": asset.type,
      "Cache-Control": asset.cache,
      "X-Content-Type-Options": "nosniff",
    };

    // Serve from the ASSETS binding when configured (static asset deployment)
    if (env && env.ASSETS) {
      const res = await env.ASSETS.fetch(new URL("/" + asset.file, url.origin));
      if (res.ok) {
        const h = new Headers(res.headers);
        h.set("Content-Type", asset.type);
        h.set("Cache-Control", asset.cache);
        h.set("X-Content-Type-Options", "nosniff");
        return new Response(res.body, { status: 200, headers: h });
      }
    }

    // Fallback: inline bundle (single-file worker deployment)
    const inline = ASSETS_JSON[asset.file];
    if (inline !== undefined) {
      return new Response(decodeAsset(inline), { status: 200, headers });
    }

    return new Response("Seedling Kenya — not found", { status: 404, headers: { "Content-Type": "text/plain" } });
  },
};

